pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numCalls) public {
        numCalls = bound(numCalls, 1, 10);
        uint256 totalSent = 0;
        uint256 totalFeePaid = 0;
        bool winnerOccurred = false;
        for (uint256 i = 0; i < numCalls; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            totalSent += 10;
            if (!winnerOccurred && uint256(keccak256(abi.encode(block.timestamp, block.difficulty, i))) % 2 == 0) {
                winnerOccurred = true;
            }
            if (uint256(keccak256(abi.encode(block.timestamp, block.difficulty, i))) % 2 == 0) {
                totalFeePaid += 1;
            }
            vm.roll(block.number + 1);
        }
        if (winnerOccurred) {
            assertTrue(c.pot() == totalSent - totalFeePaid);
        } else {
            assertTrue(c.pot() == totalSent);
        }
    }
}

