pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 playsBefore) public {
        // playsBefore limits the number of preparatory plays to prevent excessive gas usage
        playsBefore = uint8(bound(playsBefore, 0, 10));

        // Execute up to playsBefore plays; each play only proceeds if we can control the outcome via seed.
        // We warp time to influence the "random" outcome deterministically in the test.
        for (uint i = 0; i < playsBefore; i++) {
            vm.deal(address(this), 10 ether);
            // Use seed+i as the new timestamp to create a different random outcome per iteration.
            vm.warp(seed + i);
            // try/catch handles random==1 case where no transfer occurs and the call still succeeds
            try c.play{value: 10}() {} catch {}
        }

        // Record the pot before the final, decisive play.
        uint256 potBefore = c.pot();

        // Set up the decisive play: provide exactly the ticket amount.
        vm.deal(address(this), 10 ether);
        // Warp to a timestamp that, together with default difficulty, makes random == 0.
        // With block.difficulty == 0 (default in foundry), we need keccak256(abi.encodePacked(timestamp, 0)) % 2 == 0.
        // We can iterate locally to find a suitable timestamp, but we let the fuzzer supply seed 
        // and we adjust to guarantee random == 0 only when it matters.
        // To guarantee random == 0 regardless of seed, we set difficulty to 0 and iterate warp until condition met.
        // However, vm.roll/vm.difficulty are not allowed; we rely on block.difficulty defaulting to 0.
        // For any seed there exists some timestamp where keccak256(abi.encodePacked(timestamp,0)) % 2 == 0.
        // We'll just use seed as timestamp and if random != 0, we skip the assertion (the rule about pot decreasing after a win only applies if random == 0).
        vm.warp(seed);
        bool won;
        try c.play{value: 10}() {
            won = true;
        } catch {
            won = false;
        }

        // The property only applies when the play succeeds (no revert) and we know it was a win.
        // The reference contract only transfers when random == 0, so if transfer occurred, won == true.
        if (won) {
            uint256 potAfter = c.pot();
            // After a win, pot must have decreased because the winner claimed it.
            // In the buggy version, pot never increases, so potBefore == potAfter (or underflow reverts, already a failure).
            // If the underflow reverts, won would be false, so we don't get here.
            // Thus, this assertion captures the difference: reference reduces pot, buggy keeps it same.
            assertTrue(potAfter < potBefore);
        }
        // If won == false, the property is vacuously true for this input.
    }
}

