pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numCalls, uint8 winMask) public {
        uint256 calls = bound(numCalls, 1, 10);
        uint256 mask = uint256(winMask);
        vm.deal(address(this), 1000 ether);
        bool lastWon = false;
        for (uint256 i = 0; i < calls; i++) {
            bool willWin = ((mask >> (i % 8)) & 1) == 1;
            if (willWin) {
                vm.roll(block.number + 1);
                vm.warp(block.timestamp + 12 + (block.number % 2 == 0 ? 0 : 1));
                while (uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 != 0) {
                    vm.warp(block.timestamp + 12);
                    vm.roll(block.number + 1);
                }
            } else {
                vm.roll(block.number + 1);
                vm.warp(block.timestamp + 12 + (block.number % 2 == 0 ? 1 : 0));
                while (uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 != 1) {
                    vm.warp(block.timestamp + 12);
                    vm.roll(block.number + 1);
                }
            }
            c.play{value: 10}();
            lastWon = willWin;
        }
        uint256 potAfter = c.pot();
        bool invariantHolds = lastWon ? potAfter == 0 : true;
        assertTrue(invariantHolds);
    }
}

