pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 count) public {
        // Keep count in a reasonable range to avoid infinite loops; the fuzzer will explore many values
        uint256 n = bound(count, 1, 20);
        address player = address(0x100);
        vm.deal(player, n * 10 ether);
        vm.startPrank(player);

        uint256 totalPaid = 0;
        uint256 totalWon = 0;
        for (uint256 i = 0; i < n; i++) {
            c.play{value: 10}();
            totalPaid += 10;
            // After each call, read pot. If pot decreased (a win occurred), record the amount won.
            // Since pot only decreases on a win by (pot_before_win - 0) after transfers, we can approximate.
            // But the reference resets pot to 0 on a win. We track net contributions instead.
        }
        vm.stopPrank();

        // General invariant: pot is always less than or equal to totalPaid minus totalWon * (10 - 1)?
        // Better: pot reflects only contributions since the last win, so pot < 20 always (since max two contributions without win).
        // Actually, the invariant is: pot is always less than 20 (since it resets to 0 on win and max two contributions before reset).
        // The buggy version can accumulate pot indefinitely.
        // Strong invariant: pot < 20 for the reference. Buggy: pot can grow > 20.
        assertTrue(c.pot() < 20);
    }
}

