pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 fuzzSeed) public {
        // fuzzSeed determines the random outcomes via block.timestamp and block.difficulty
        vm.assume(fuzzSeed > 0);

        // Set up block variables to force a win (random == 0) on first call
        vm.warp(1000);
        vm.roll(uint256(keccak256(abi.encode(fuzzSeed))) % 100);

        // Actor for calls
        address actor = address(0x100);
        vm.deal(actor, 100 ether);

        // First play: force a win by iterating until random == 0
        vm.startPrank(actor);
        // Try a few timestamps to ensure first call wins
        for (uint i = 0; i < 10; i++) {
            vm.warp(1000 + i);
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                break;
            }
        }
        c.play{value: 10}();

        // Second play: force a loss by iterating until random == 1
        for (uint i = 10; i < 20; i++) {
            vm.warp(1000 + i);
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 1) {
                break;
            }
        }
        c.play{value: 10}();
        vm.stopPrank();

        // After a win followed by a loss, reference pot == 10, buggy pot == 11
        // The invariant: pot % 10 != 1
        assertTrue(c.pot() % 10 != 1);
    }
}

